function S({registerIndicator:h,sourceValues:f,nulls:y}){h({id:"oa-weibulldist",name:"Weibull Distribution CDF (WEIBULLDIST)",category:"Numerics",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"period",type:"number",label:"Period",default:50,min:1,max:1e3,step:1},{key:"shape",type:"number",label:"Shape (k)",default:2,min:.01,max:100,step:.1,tooltip:"Below 1 gives a concave curve, 1 is the exponential case, 2 the Rayleigh case, above 3 an S-curve."},{key:"scale",type:"number",label:"Scale (lambda)",default:.5,min:.01,max:100,step:.1,tooltip:"A larger scale makes the curve rise more slowly, a smaller one saturates it sooner."}],plots:[{key:"weibull",type:"line",title:"WEIBULLDIST",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:.5,title:"Midline",color:"#787b86",dashed:!0},{price:.95,title:"Upper",color:"#ef5350",dashed:!0},{price:.05,title:"Lower",color:"#26a69a",dashed:!0}],calc(s,t){const x=Math.max(1,Math.floor(Number(t.period)||50)),v=Math.max(.01,Number(t.shape)||2),N=Math.max(.01,Number(t.scale)||.5),l=f(s,t.source??"close"),p=new Array(s.length).fill(NaN);for(let e=0;e<s.length;e++){const r=Number.isFinite(l[e])?l[e]:0;let c=r,a=r;const n=x-1,m=n>=1?1:-1;for(let o=1;m>0?o<=n:o>=n;o+=m){const u=e-o,i=u>=0&&Number.isFinite(l[u])?l[u]:0;i>c&&(c=i),i<a&&(a=i)}const d=c-a,w=d===0?.5:(r-a)/d,M=Math.max(0,w),k=Math.pow(M/N,v),b=1-Math.exp(-k);Number.isFinite(b)&&(p[e]=b)}return{weibull:y(p)}}})}export{S as default};
